INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66504512', 66504512, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA JAKARTA SMART CITY', 'Pengadaan Tenaga Ahli AI Engineer Pengembangan Produk dan Layanan April 1 #1', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 16775000, 'March 2026', 'APBD', 1, 1, '1 orang x 1 bulan', '1. Melakukan perancangan arsitektur solusi AI yang ideal dan reliable secara komprehensif sesuai dengan kebutuhan organisasi, serta menentukan pendekatan model, alur data, dan komponen sistem AI yang mendukung skalabilitas, keamanan, dan kinerja optimal; 2. Mengimplementasikan model dan pipeline AI berdasarkan pedoman dan kebutuhan analitis yang telah ditentukan, serta menyusun kode dan eksperimen yang berkualitas tinggi untuk memastikan model berfungsi sesuai spesifikasi dan standar yang ditetapkan; 3. Mengoptimalkan performa model dan pipeline AI dengan memantau dan menganalisis hasil prediksi, mendeteksi masalah seperti bias, drift, atau penurunan performa, serta melakukan pemeliharaan dan peningkatan berkala agar kinerja tetap optimal; 4. Bekerja secara efektif dalam tim lintas fungsi untuk mengembangkan solusi AI yang berkualitas tinggi, serta berpartisipasi aktif dalam pertemuan tim untuk membahas pendekatan teknis, tantangan yang muncul, dan penyelesaian masalah secara kolaboratif; dan 5. Mengikuti perkembangan teknologi terkini seputar Artificial Intelligence, termasuk Machine Learning, Deep Learning, MLOps, dan teknologi terkait, serta memastikan diri tetap mengikuti informasi dan tren yang dapat meningkatkan efektivitas pengembangan solusi AI.', 'Tenaga Ahli Utama Spesifikasi: S1 Pengalaman Minimal 4 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2810836);
