INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66505912', 66505912, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior Penyusunan Kajian Kebijakan Penguatan Regulasi Manajemen Risiko Pembangunan Nasional (MRPN)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 72000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 PAKET', 'Lingkup kegiatan dan tanggung jawab untuk Jasa Konsultan Junior Penyusunan Kajian Kebijakan Penguatan Regulasi Manajemen Risiko Pembangunan Nasional (MRPN) adalah melakukan asistensi analisis dan telaah hukum terhadap peraturan perundang-undangan yang terkait dengan kebijakan manajemen risiko pembangunan nasional, penyusunan kajian dan rekomendasi kebijakan serta opsi penguatan regulasi, membuat analisis sinkronisasi regulasi lintas sektor, pendampingan konseptual dan strategis dalam proses perumusan kebijakan, penyediaan referensi best practices dan benchmarking, serta pelaksanaan kegiatan knowledge sharing sebagai bahan pertimbangan pengambilan Keputusan.', 'Hasil kerja Jasa Konsultan Junior Penyusunan Kajian Kebijakan Penguatan Regulasi Manajemen Risiko Pembangunan Nasional (MRPN) ini adalah Laporan Penyusunan Kajian Kebijakan Penguatan Regulasi Manajemen Risiko Pembangunan Nasional (MRPN) dengan waktu penyelesaian selama 9 (sembilan) bulan. Jasa Konsultan Junior Penyusunan Kajian Kebijakan Penguatan Regulasi Manajemen Risiko Pembangunan Nasional (MRPN) dalam mendukung Pekerjaan Direktorat Sistem dan Manajemen Risiko memiliki keluaran setiap terminnya sebagai berikut: No Periode Keluaran per Termin 1 Termin 1 Laporan Analisis dan Telaah Hukum Regulasi MRPN 2 Termin 2 Laporan Kajian dan Rekomendasi Penguatan Kebijakan dan Regulasi MRPN 3 Termin 3 Laporan Analisis Sinkronisasi Regulasi Lintas Sektor. 4 Termin 4 Laporan Pendampingan Konseptual dan Strategis Perumusan Kebijakan MRPN. 5 Termin 5 Laporan Penyusunan Kajian Kebijakan Penguatan Regulasi Manajemen Risiko Pembangunan Nasional (MRPN)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2811634);
