INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66506559', 66506559, 'analyze_legacy', 'Kota Balikpapan', 'kabkota', 'UPTD-RUMAH SAKIT UMUM DAERAH', 'Renovasi Rawat Jalan dan Rawat Inap', 'Pekerjaan Konstruksi', 'Pengadaan Langsung', 'Kalimantan Timur, Balikpapan (Kota)', 1350000000, 'January 2026', 'BLUD', 1, 1, '1 Paket', 'Uraian pekerjaan meliputi pelaksanaan renovasi bangunan pada area rawat jalan dan rawat inap dengan melakukan pembongkaran terbatas pada bagian bangunan eksisting yang terdampak, pekerjaan perbaikan dan peningkatan kualitas dinding, lantai, dan plafon, penataan ulang fungsi dan tata letak ruang, serta penyesuaian instalasi pendukung sesuai kebutuhan pelayanan. Pada area rawat jalan dilakukan pembangunan Poli Eksekutif dan perbaikan ruang poli lainnya, sedangkan pada area rawat inap dilakukan renovasi kamar VIP serta pemindahan dan penataan ruang Perinatologi ke area yang bersebelahan dengan ICU, dengan seluruh pekerjaan dilaksanakan secara bertahap, terkoordinasi, dan tetap menjaga keselamatan, kebersihan, serta kelangsungan operasional pelayanan rumah sakit.', 'Spesifikasi pekerjaan meliputi renovasi bangunan rawat jalan dan rawat inap dalam rangka peningkatan mutu pelayanan rumah sakit, dengan kegiatan berupa pembuatan Poli Eksekutif pada area rawat jalan melalui penataan ulang ruang, perbaikan elemen bangunan, serta penyesuaian instalasi pendukung, perbaikan ruang poli rawat jalan lainnya berupa perbaikan dinding, lantai, dan plafon, renovasi ruang rawat inap untuk pembuatan kamar VIP dengan peningkatan kenyamanan, privasi, dan fasilitas pasien, serta pemindahan dan penataan ulang ruang Perinatologi ke area yang bersebelahan dengan ICU guna mendukung pelayanan intensif, dengan seluruh pekerjaan dilaksanakan secara bertahap, memperhatikan keselamatan pasien, pengendalian infeksi, dan tetap menjaga kelangsungan operasional rumah sakit.', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 2812301);
