INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66506717', 66506717, 'analyze_legacy', 'Badan Riset dan Inovasi Nasional', 'central', 'Deputi Bidang Infrastruktur Riset dan Inovasi', 'Pengadaan Dosimeter TLD/OSLD untuk Kebutuhan Kurva Kalibrasi Laboratorium Teknologi Radiasi', 'Barang', 'E-Purchasing', 'Banten, Tangerang Selatan (Kota)', 870700000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Pengadaan dosimeter untuk mendukung layanan pembacaan dosimeter dan penyusunan kurva kalibrasi di Laboratorium Teknologi Radiasi, meliputi dosimeter whole body, eye dosimeter, ring/extremity dosimeter, dan dosimeter OSL, termasuk aksesori/holder yang melekat pada barang apabila dipersyaratkan, dokumentasi produk, serta jaminan mutu/purna jual sesuai ketentuan.', 'Pengadaan dosimeter TLD/OSLD untuk kebutuhan kurva kalibrasi, dengan spesifikasi umum sebagai berikut: Dosimeter whole body 4 elemen, kompatibel dengan sistem pembacaan yang digunakan di laboratorium, atau setara. Dosimeter mata/eye dosimeter untuk pengukuran paparan radiasi pada lensa mata, kompatibel dengan sistem pembacaan yang digunakan di laboratorium, atau setara. Dosimeter cincin/ring/extremity untuk pengukuran paparan radiasi pada ekstremitas, kompatibel dengan sistem pembacaan yang digunakan di laboratorium, atau setara. Dosimeter OSL whole body dengan identifikasi/serial unik dan media baca yang sesuai, atau setara. Dosimeter TLD 2 elemen dengan identifikasi QR code/serial unik, atau setara. Ketentuan umum spesifikasi: Barang baru, bukan barang bekas/rekondisi. Memiliki kualitas, fungsi, dan kinerja yang setara dengan kebutuhan layanan laboratorium. Kompatibel dengan sistem, metode kerja, atau peralatan pembacaan yang tersedia di laboratorium, atau tersedia solusi integrasi yang setara. Dilengkapi informasi teknis/katalog/datasheet. Penyedia memberikan dukungan purna jual, garansi, dan/atau dukungan teknis sesuai ketentuan yang berlaku. Rincian kebutuhan untuk mendukung spesifikasi Dosimeter whole body 4 elemen: 70 pcs Eye dosimeter: 70 pcs Ring/extremity dosimeter: 70 pcs OSL whole body dosimeter: 50 pcs TLD 2 elemen dengan QR code: 70 pcs Kebutuhan tersebut sesuai daftar pada telaah staf pengadaan dosimeter TLD/OSLD untuk kurva kalibrasi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2813267);
